head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > E > oneditenter]<br/>입력창에서 Enter 키 또는 Tab 키 입력시 발생합니다.",
    "validation" : [
        "입력창에서 Enter 키 입력 시 이벤트가 발생합니다.",
        "입력창에서 Tab 키 입력 시 이벤트가 발생합니다.",
        "반환값이 true(default) 인 경우 Tab 키 입력 시 nextTabID(start) 로 포커스가 이동합니다.",
        "반환값이 true(default), nextTabByEnter 가 true 인 경우 Enter 키 입력 시 nextTabID(start) 로 포커스가 이동되어야 합니다.",
        "반환값이 true(default), nextTabByEnter 가 미설정, enterBlur 가 true 인 경우 Enter 키 입력 시 포커스가 해제되어야 합니다.",
        "반환값이 false 인 경우 Tab 키 입력 시 nextTabID(start) 가 아닌 곳으로 포커스가 이동합니다.",
        "반환값이 false, nextTabByEnter 가 true, enterBlur 가 false 인 경우 Enter 키 입력 시 포커스가 유지되어야 합니다.",
        "Shift+Enter 키 또는 Shift+Tab 키 입력시에도 이벤트가 발생합니다.",
    ]
}



scwin.wf_sample_onwframeload = function () {
    // 테스트 설명, 유효성 생성
    let wf_body_left = wf_sample.getObj("wf_body_left");
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
      // 기존 target 있으면 삭제
    if (typeof startcomp !== 'undefined') {
        startcomp.remove();
    }

    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (startcomp)   
    let properties = {
        tabIndex : 1,             
    };

    // 조건 설정 (target)   
    let properties2 = {
        tabIndex : 2,
        nextTabID: "startcomp",  
        nextTabByEnter: wf_sample.getObj("con_nextTabByEnter").getText(),
        enterBlur: wf_sample.getObj("con_enterBlur").getText(),
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onfocus"], 'startcomp');

    let cList2 = $c.gcm.createCList(properties2);  
    let eList2 = $c.gcm.createEList(["onfocus", "onblur", "oneditenter"]);  

    $c.gcm.createBasicInput(cList, eList, 'startcomp');  
    $c.gcm.createBasicInput(cList2, eList2, 'target1');

    startcomp.setValue("start");
    target1.setValue("target1");
}
